// Utility helper untuk memastikan logo & gambar MapahTrip tidak pernah rusak (broken image)
// Mendukung auto-fallback ke public path, GitHub Pages path, dan embedded base64 sebagai jaminan 100% tampil

export const LOGO_HITAM_BASE64 = 'data:image/png;base64,';
export const LOGO_PUTIH_BASE64 = 'data:image/png;base64,';

export const handleImageFallback = (
  e: React.SyntheticEvent<HTMLImageElement, Event>,
  fallbacks: string[]
) => {
  const img = e.currentTarget;
  const currentIndex = parseInt(img.dataset.fallbackStep || '0', 10);
  if (currentIndex < fallbacks.length) {
    img.dataset.fallbackStep = String(currentIndex + 1);
    img.src = fallbacks[currentIndex];
  }
};

export const getLogoHitamFallbacks = () => [
  './mapahtrip_logo_hitam.png',
  '/Mapahtrip/mapahtrip_logo_hitam.png',
  '/mapahtrip_logo_hitam.png',
  LOGO_HITAM_BASE64,
];

export const getLogoPutihFallbacks = () => [
  './mapahtrip_logo_putih.png',
  '/Mapahtrip/mapahtrip_logo_putih.png',
  '/mapahtrip_logo_putih.png',
  LOGO_PUTIH_BASE64,
];

export const getBuildingPhotoFallbacks = () => [
  './MapahTrip.jpg',
  '/Mapahtrip/MapahTrip.jpg',
  '/MapahTrip.jpg',
];
